-# vite-plus-starter
+# @catlas/solid-ol

-A starter for creating a Vite Plus project.
+Solid bindings for OpenLayers. The package is browser-only for now and does not provide SSR support.
+
+## Basic usage
+
+```tsx
+import { createSignal } from "solid-js";
+import OlMap from "ol/Map.js";
+import OSM from "ol/source/OSM.js";
+import TileLayer from "ol/layer/Tile.js";
+import View from "ol/View.js";
+import "ol/ol.css";
+import { Map } from "@catlas/solid-ol";
+
+const layers = [new TileLayer({ source: new OSM() })];
+const view = new View({ center: [0, 0], zoom: 2 });
+
+const createMap = (target: HTMLDivElement, options: MapOptions) =>
+  new OlMap({ ...options, target });
+
+function App() {
+  const [options] = createSignal({ layers, view });
+
+  return <Map class="map" options={options} createMap={createMap} />;
+}
+```
+
+`Map` creates the target element internally. Consumers do not need `ref` or `onMount`.
+
+## OpenLayers children
+
+Use `useMap` and `MapItem` to attach any OpenLayers object to the map:
+
+```tsx
+<Map options={options} createMap={createMap}>
+  <MapItem
+    value={layer}
+    attach={(map, layer) => {
+      map.addLayer(layer);
+      return () => map.removeLayer(layer);
+    }}
+  />
+</Map>
+```
+
+`MapItem` detaches the previous value before attaching a replacement. Custom child components can use `useMap()` directly. A child that returns DOM is rendered into the map target.
+
+When access to the map instance is needed outside JSX, use `createMapBinding`:
+
+```tsx
+const binding = createMapBinding({
+  options,
+  createMap,
+  targetProps: { class: "map" },
+});
+
+binding.map.renderSync();
+return binding.target;
+```

 ## Development
*** End Patch";
